function installOption() {
    const night = document.getElementById("mod-night-theme");
    const group = night?.parentElement;
    if (!night || !group || !christmasAvailable) return;
    let option = group.querySelector<HTMLElement>("#mod-christmas-option");
    if (!option) {
        option = night.cloneNode(true) as HTMLElement;
        option.id = "mod-christmas-option";
        option.removeAttribute("data-gtm");
        option.setAttribute("aria-label", "Weergave christmas");
        const image = option.querySelector("img");
        if (image) {
            image.src = `data:image/svg+xml,${encodeURIComponent(christmasRoom())}`;
            image.alt = "Kerst";
        }
        const label = option.querySelector("label");
        if (label) {
            const logo = label.querySelector("svg")?.cloneNode(true);
            label.textContent = "Kerst ";
            if (logo) label.append(logo);
        }
        const ribbon = document.createElement("span");
        ribbon.className = "mod-christmas-ribbon";
        ribbon.textContent = "Tijdelijk";
        option.append(ribbon);
        const radio = option.querySelector("input");
        if (radio) {
            radio.value = "christmas";
            radio.name = "mod-christmas-theme";
            radio.checked = false;
        }
        group.classList.add("mod-winter-options", "mod-christmas-options");
        (group.querySelector("#mod-winter-option") || night).after(option);
        const select = (event: Event) => {
            event.preventDefault();
            event.stopPropagation();
            set("winterTheme", false);
            set("christmasTheme", true);
            winterTheme();
            christmasTheme();
            setBackground();
        };
        option.addEventListener("click", select);
        option.addEventListener("keydown", (event) => {
            if (event.key === "Enter" || event.key === " ") select(event);
        });
        group.addEventListener(
            "click",
            (event) => {
                if (
                    !(event.target instanceof Element) ||
                    event.target.closest("#mod-christmas-option, #mod-winter-option") ||
                    !event.target.closest('.container[role="radio"]') ||
                    !christmasEnabled()
                )
                    return;
                set("christmasTheme", false);
                christmasTheme();
                setBackground();
            },
            true,
        );
    }
    const enabled = christmasEnabled();
    option.setAttribute("aria-checked", String(enabled));
    const radio = option.querySelector("input");
    if (radio) radio.checked = enabled;
    group.classList.toggle("mod-christmas-selected", enabled);
    if (enabled) {
        for (const native of group.querySelectorAll<HTMLElement>(
            '.container[role="radio"]:not(#mod-christmas-option)',
        )) {
            if (native.getAttribute("aria-checked") !== "false")
                native.setAttribute("aria-checked", "false");
            const input = native.querySelector("input");
            if (input?.checked) input.checked = false;
        }
    }
}


export function christmasTheme() { if (!document.getElementById("mod-christmas-style")) { const style = document.createElement("style"); style.id = "mod-christmas-style"; style.textContent = css; document.head.append(style); } const enabled = christmasEnabled(); document.documentElement.classList.toggle("mod-christmas", enabled); if (enabled && !document.getElementById("mod-christmas-room")) { const layer = document.createElement("div"); layer.id = "mod-christmas-room"; layer.setAttribute("aria-hidden","true"); layer.innerHTML = christmasRoom(); document.getElementById("somtoday-mod")?.append(layer); } else if (!enabled) document.getElementById("mod-christmas-room")?.remove(); installOption(); }
